<?php require 'includes/functions.php';$pageTitle='Contact Us';$errors=[];if(post()){verify_csrf();$name=textval('name');$email=textval('email');$message=textval('message');if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';if(mb_strlen($message)<10||mb_strlen($message)>5000)$errors[]='Message must be 10–5000 characters.';if(time()-($_SESSION['contact_at']??0)<30)$errors[]='Please wait 30 seconds before sending another message.';if(!$errors){query('INSERT INTO messages(name,email,message) VALUES (?,?,?)',[$name,$email,$message]);$_SESSION['contact_at']=time();flash('Thank you. Your message has been received.');redirect('contact.php');}}require 'includes/header.php';?><div class="page-head"><div class="container"><span class="eyebrow">WE ARE HERE TO HELP</span><h1>Let's talk fragrance.</h1></div></div><section class="container section contact-grid"><div class="panel"><h2>Send us a message</h2><?php errors($errors);?><form method="post" data-validate><?php csrf();?><label>Your name<input name="name" minlength="2" maxlength="100" required autocomplete="name" value="<?=e(textval('name'))?>"></label><label>Email address<input type="email" name="email" maxlength="190" required autocomplete="email" value="<?=e(textval('email'))?>"></label><label>Message<textarea name="message" rows="6" minlength="10" maxlength="5000" required><?=e(textval('message'))?></textarea></label><button>Send message</button></form></div><aside><span class="eyebrow">FALCON PERFUMES</span><h2>A little guidance.<br>A lasting impression.</h2><p class="muted">Have a question about a fragrance, your order or delivery? Send your query and our team will review it.</p><div class="panel"><h3>Order enquiries</h3><p>Include your order number so we can help you faster.</p><a href="<?=e(url('dashboard.php'))?>">View your orders →</a></div></aside></section><?php require 'includes/footer.php';?>
